-- IPA公式問題の原文を復元する。登録済みの選択肢IDと解説は保持する。
with originals(id, body, source, choices) as (values
  ('DMQ-0062', 'NoSQLの一種である、グラフ指向DBの特徴として、適切なものはどれか。', '出典：令和3年度 春期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "データ項目の値として階層構造のデータをドキュメントとしてもつことができる。また、ドキュメントに対しインデックスを作成することもできる。"}, {"id": 2, "body": "ノード、リレーション、プロパティで構成され、ノード間をリレーションでつないで構造化する。ノード及びリレーションはプロパティをもつことができる。"}, {"id": 3, "body": "一つのキーに対して一つの値をとる形をしている。値の型は定義されていないので、様々な型の値を格納することができる。"}, {"id": 4, "body": "一つのキーに対して複数の列をとる形をしている。関係データベースとは異なり、列の型は固定されていない。"}]'::jsonb),
  ('DMQ-0064', 'データレイクの特徴はどれか。', '出典：令和3年度 春期 応用情報技術者試験 午前 問31（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "大量のデータを分析し、単なる検索だけでは分からない隠れた規則や相関関係を見つけ出す。"}, {"id": 2, "body": "データウェアハウスに格納されたデータから特定の用途に必要なデータだけを取り出し、構成する。"}, {"id": 3, "body": "データウェアハウスやデータマートからデータを取り出し、多次元分析を行う。"}, {"id": 4, "body": "必要に応じて加工するために、データを発生したままの形で格納する。"}]'::jsonb),
  ('DMQ-0065', 'レコメンデーション（お勧め商品の提案）の例のうち、協調フィルタリングを用いたものはどれか。', '出典：令和3年度 春期 応用情報技術者試験 午前 問63（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "多くの顧客の購買行動の類似性を相関分析などによって求め、顧客Aに類似した顧客Bが購入している商品を顧客Aに勧める。"}, {"id": 2, "body": "カテゴリ別に売れ筋商品のランキングを自動抽出し、リアルタイムで売れ筋情報を発信する。"}, {"id": 3, "body": "顧客情報から、年齢、性別などの人口動態変数を用い、“20代男性”、“30代女性”などにセグメント化した上で、各セグメント向けの商品を提示する。"}, {"id": 4, "body": "野球のバットを購入した人に野球のボールを勧めるなど商品間の関連に着目して、関連商品を提示する。"}]'::jsonb),
  ('DMQ-0066', '系統図法の活用例はどれか。', '出典：令和3年度 春期 応用情報技術者試験 午前 問76（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "解決すべき問題を端か中央に置き、関係する要因を因果関係に従って矢印でつないで周囲に並べ、問題発生に大きく影響している重要な原因を探る。"}, {"id": 2, "body": "結果とそれに影響を及ぼすと思われる要因との関連を整理し、体系化して、魚の骨のような形にまとめる。"}, {"id": 3, "body": "事実、意見、発想を小さなカードに書き込み、カード相互の親和性によってグループ化して、解決すべき問題を明確にする。"}, {"id": 4, "body": "目的を達成するための手段を導き出し、更にその手段を実施するための幾つかの手段を考えることを繰り返し、細分化していく。"}]'::jsonb),
  ('DMQ-0069', '分散データベースにおける“複製に対する透過性”の説明として、適切なものはどれか。', '出典：令和3年度 秋期 応用情報技術者試験 午前 問30（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "それぞれのサーバのDBMSが異種でも、プログラムはDBMSの相違を意識する必要がない。"}, {"id": 2, "body": "一つの表が複数のサーバに分割されて配置されていても、プログラムは分割された配置を意識する必要がない。"}, {"id": 3, "body": "表が別のサーバに移動されても、プログラムは表が配置されたサーバを意識する必要がない。"}, {"id": 4, "body": "複数のサーバに一つの表が重複して存在しても、プログラムは表の重複を意識する必要がない。"}]'::jsonb),
  ('DMQ-0050', 'ANSI/SPARC 3層スキーマモデルにおける内部スキーマの設計に含まれるものはどれか。', '出典：令和4年度 春期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "SQL問合せ応答時間の向上を目的としたインデックスの定義"}, {"id": 2, "body": "エンティティ間の“1対多”、“多対多”などの関連を明示するE-Rモデルの作成"}, {"id": 3, "body": "エンティティ内やエンティティ間の整合性を保つための一意性制約や参照制約の設定"}, {"id": 4, "body": "データの冗長性を排除し、更新の一貫性と効率性を保持するための正規化"}]'::jsonb),
  ('DMQ-0052', 'ビッグデータの利用におけるデータマイニングを説明したものはどれか。', '出典：令和4年度 春期 応用情報技術者試験 午前 問30（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "蓄積されたデータを分析し、単なる検索だけでは分からない隠れた規則や相関関係を見つけ出すこと"}, {"id": 2, "body": "データウェアハウスに格納されたデータの一部を、特定の用途や部門用に切り出して、データベースに格納すること"}, {"id": 3, "body": "データ処理の対象となる情報を基に規定した、データの構造、意味及び操作の枠組みのこと"}, {"id": 4, "body": "データを複数のサーバに複製し、性能と可用性を向上させること"}]'::jsonb),
  ('DMQ-0053', 'XBRLで主要な取扱いの対象とされる情報はどれか。', '出典：令和4年度 春期 応用情報技術者試験 午前 問71（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "医療機関のカルテ情報"}, {"id": 2, "body": "企業の顧客情報"}, {"id": 3, "body": "企業の財務情報"}, {"id": 4, "body": "自治体の住民情報"}]'::jsonb),
  ('DMQ-0055', 'AIにおける過学習の説明として、最も適切なものはどれか。', '出典：令和4年度 秋期 応用情報技術者試験 午前 問4（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "ある領域で学習した学習済みモデルを、別の領域に再利用することによって、効率的に学習させる。"}, {"id": 2, "body": "学習に使った訓練データに対しては精度が高い結果となる一方で、未知のデータに対しては精度が下がる。"}, {"id": 3, "body": "期待している結果とは掛け離れている場合に、結果側から逆方向に学習させて、その差を少なくする。"}, {"id": 4, "body": "膨大な訓練データを学習させても効果が得られない場合に、学習目標として成功と判断するための報酬を与えることによって、何が成功か分かるようにする。"}]'::jsonb),
  ('DMQ-0056', '予測手法の一つであるデルファイ法の説明はどれか。', '出典：令和4年度 秋期 応用情報技術者試験 午前 問75（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "現状の指標の中に将来の動向を示す指標があることに着目して予測する。"}, {"id": 2, "body": "将来予測のためのモデル化した連立方程式を解いて予測する。"}, {"id": 3, "body": "同時点における複数の観測データの統計比較分析によって将来を予測する。"}, {"id": 4, "body": "複数の専門家へのアンケートの繰返しによる回答の収束によって将来を予測する。"}]'::jsonb),
  ('DMQ-0057', 'BASE特性を満たし、次の特徴をもつNoSQLデータベースシステムに関する記述のうち、適切なものはどれか。

〔NoSQLデータベースシステムの特徴〕
・ネットワーク上に分散した複数のノードから構成される。
・一つのノードでデータを更新した後、他の全てのノードにその更新を反映する。', '出典：令和4年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問1（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "クライアントからの更新要求を2相コミットによって全てのノードに反映する。"}, {"id": 2, "body": "データの更新結果は、システムに障害がなければ、いつかは全てのノードに反映される。"}, {"id": 3, "body": "同一の主キーの値による同時の参照要求に対し、全てのノードは同じ結果を返す。"}, {"id": 4, "body": "ノード間のネットワークが分断されると、クライアントからの処理要求を受け付けなくなる。"}]'::jsonb),
  ('DMQ-0042', '各種センサーを取り付けた航空機のエンジンから飛行中に収集したデータを分析し、仮想空間に構築したエンジンのモデルに反映してシミュレーションを行うことによって、各パーツの消耗状況や交換時期を正確に予測できるようになる。このように産業機器などにIoT技術を活用し、現実世界や物理的現象をリアルタイムに仮想空間で忠実に再現することを表したものはどれか。', '出典：令和5年度 春期 応用情報技術者試験 午前 問73（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "サーバ仮想化"}, {"id": 2, "body": "スマートグリッド"}, {"id": 3, "body": "スマートメーター"}, {"id": 4, "body": "デジタルツイン"}]'::jsonb),
  ('DMQ-0044', '関係モデルにおける外部キーの説明として、適切なものはどれか。', '出典：令和5年度 秋期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "ある関係の候補キーを参照する属性、又は属性の組"}, {"id": 2, "body": "主キー以外で、タプルを一意に識別できる属性、又は属性の組"}, {"id": 3, "body": "タプルを一意に識別できる属性、又は属性の組の集合のうち極小のもの"}, {"id": 4, "body": "タプルを一意に識別できる属性、又は属性の組を含む集合"}]'::jsonb),
  ('DMQ-0045', '市場を消費者特性でセグメント化する際に、基準となる変数を、地理的変数、人口統計的変数、心理的変数、行動的変数に分類するとき、人口統計的変数に分類されるものはどれか。', '出典：令和5年度 秋期 応用情報技術者試験 午前 問69（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "社交性などの性格"}, {"id": 2, "body": "職業"}, {"id": 3, "body": "人口密度"}, {"id": 4, "body": "製品の使用割合"}]'::jsonb),
  ('DMQ-0046', '発生した故障について、発生要因ごとの件数の記録を基に、故障発生件数で上位を占める主な要因を明確に表現するのに適している図法はどれか。', '出典：令和5年度 秋期 応用情報技術者試験 午前 問76（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "特性要因図"}, {"id": 2, "body": "パレート図"}, {"id": 3, "body": "マトリックス図"}, {"id": 4, "body": "連関図"}]'::jsonb),
  ('DMQ-0047', '匿名加工情報取扱事業者が、適正な匿名加工を行った匿名加工情報を第三者提供する際の義務として、個人情報保護法に規定されているものはどれか。', '出典：令和5年度 秋期 応用情報技術者試験 午前 問79（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "第三者に提供される匿名加工情報に含まれる個人に関する情報の項目及び提供方法を公表しなければならない。"}, {"id": 2, "body": "第三者へ提供した場合は、速やかに個人情報保護委員会へ提供した内容を報告しなければならない。"}, {"id": 3, "body": "第三者への提供の手段は、ハードコピーなどの物理的な媒体を用いることに限られる。"}, {"id": 4, "body": "匿名加工情報であっても、第三者提供を行う際には事前に本人の承諾が必要である。"}]'::jsonb),
  ('DMQ-0048', '大文字のアルファベットで始まる膨大な数のデータを、規則に従って複数のノードに割り当てる。このようにあらかじめ定めた規則に従って、複数のノードにデータを分散して割り当てる方法はどれか。

〔規則〕
・データの先頭文字がA〜Gの場合はノード1に格納する。
・データの先頭文字がH〜Nの場合はノード2に格納する。
・データの先頭文字がO〜Zの場合はノード3に格納する。', '出典：令和5年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問2（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "2相コミットプロトコル"}, {"id": 2, "body": "コンシステントハッシング"}, {"id": 3, "body": "シャーディング"}, {"id": 4, "body": "レプリケーション"}]'::jsonb)
)
update study.questions as q
set body = o.body,
    source = o.source,
    choices = (
      select jsonb_agg(old.choice || jsonb_build_object('body', exact.choice->>'body') order by old.position)
      from jsonb_array_elements(q.choices) with ordinality as old(choice, position)
      join jsonb_array_elements(o.choices) as exact(choice) on old.choice->>'id' = exact.choice->>'id'
    )
from originals as o
where q.id = o.id and q.origin = 'ipa_past'
returning q.id;
-- IPA公式問題の原文を復元する。登録済みの選択肢IDと解説は保持する。
with originals(id, body, source, choices) as (values
  ('DMQ-0051', '第1、第2、第3正規形とリレーションの特徴a、b、cの組合せのうち、適切なものはどれか。

a：どの非キー属性も、主キーの真部分集合に対して関数従属しない。
b：どの非キー属性も、主キーに推移的に関数従属しない。
c：繰返し属性が存在しない。', '出典：令和4年度 春期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "a　b　c"}, {"id": 2, "body": "a　c　b"}, {"id": 3, "body": "c　a　b"}, {"id": 4, "body": "c　b　a"}]'::jsonb),
  ('DMQ-0054', '製品100個を1ロットとして生産する。一つのロットからサンプルを3個抽出して検査し、3個とも良品であればロット全体を合格とする。100個中に10個の不良品を含むロットを合格と判定する確率は幾らか。', '出典：令和4年度 秋期 応用情報技術者試験 午前 問3（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "178/245"}, {"id": 2, "body": "405/539"}, {"id": 3, "body": "89/110"}, {"id": 4, "body": "87/97"}]'::jsonb),
  ('DMQ-0049', '従業員番号と氏名と使用できるプログラム言語を管理するために、“従業員”表及び“プログラム言語”表を設計する。“プログラム言語を2種類以上使用できる従業員がいる。プログラム言語を全く使用できない従業員もいる。”という状況を管理する“プログラム言語”表の設計として、適切なものはどれか。ここで、実線の下線は主キーを表す。

〔従業員表〕
従業員（従̲業̲員̲番̲号̲、氏名）', '出典：令和5年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問5（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "プログラム言語（氏̲名̲、プログラム言語）"}, {"id": 2, "body": "プログラム言語（従業員番号、プ̲ロ̲グ̲ラ̲ム̲言̲語̲）"}, {"id": 3, "body": "プログラム言語（従̲業̲員̲番̲号̲、プログラム言語）"}, {"id": 4, "body": "プログラム言語（従̲業̲員̲番̲号̲、プ̲ロ̲グ̲ラ̲ム̲言̲語̲）"}]'::jsonb)
)
update study.questions as q
set body = o.body,
    source = o.source,
    choices = (
      select jsonb_agg(old.choice || jsonb_build_object('body', exact.choice->>'body') order by old.position)
      from jsonb_array_elements(q.choices) with ordinality as old(choice, position)
      join jsonb_array_elements(o.choices) as exact(choice) on old.choice->>'id' = exact.choice->>'id'
    )
from originals as o
where q.id = o.id and q.origin = 'ipa_past'
returning q.id;
-- IPA公式問題の原文を復元する。登録済みの選択肢IDと解説は保持する。
with originals(id, body, source, choices, asset_key) as (values
  ('DMQ-0063', '商品の注文を記録するクラス（顧客、商品、注文、注文明細）の構造を概念データモデルで表現する。a〜dに入れるべきクラス名の組合せはどれか。ここで、顧客は何度も注文を行い、一度に一つ以上の商品を注文でき、注文明細はそれぞれ1種類の商品に対応している。また、モデルの表記にはUMLを用いる。', '出典：令和3年度 春期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "顧客　注文　注文明細　商品"}, {"id": 2, "body": "商品　注文　注文明細　顧客"}, {"id": 3, "body": "注文　注文明細　顧客　商品"}, {"id": 4, "body": "注文明細　商品　注文　顧客"}]'::jsonb, 'ipa-original/DMQ-0063.png'),
  ('DMQ-0067', '関係Rと関係Sに対して、関係Xを求める関係演算はどれか。', '出典：令和3年度 秋期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "IDで結合"}, {"id": 2, "body": "差"}, {"id": 3, "body": "直積"}, {"id": 4, "body": "和"}]'::jsonb, 'ipa-original/DMQ-0067.png'),
  ('DMQ-0068', '受注入力システムによって作成される次の表に関する記述のうち、適切なものはどれか。受注番号は受注ごとに新たに発行される番号であり、項番は1回の受注で商品コード別に連番で発行される番号である。
なお、単価は商品コードによって一意に定まる。', '出典：令和3年度 秋期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "第1正規形でない。"}, {"id": 2, "body": "第1正規形であるが第2正規形でない。"}, {"id": 3, "body": "第2正規形であるが第3正規形でない。"}, {"id": 4, "body": "第3正規形である。"}]'::jsonb, 'ipa-original/DMQ-0068.png'),
  ('DMQ-0070', 'いずれも時価100円の株式A〜Dのうち、一つの株式に投資したい。経済の成長を高、中、低の三つに区分したときのそれぞれの株式の予想値上がり幅は、表のとおりである。マクシミン原理に従うとき、どの株式に投資することになるか。', '出典：令和3年度 秋期 応用情報技術者試験 午前 問75（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "A"}, {"id": 2, "body": "B"}, {"id": 3, "body": "C"}, {"id": 4, "body": "D"}]'::jsonb, 'ipa-original/DMQ-0070.png'),
  ('DMQ-0071', '四つの表の関係を表すE-R図として、適切なものはどれか。ここで、実線の下線は主キーを、破線の下線は外部キーを表す。', '出典：令和3年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問4（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "医師 *──1 診療科 *──1 診察 1──* 患者"}, {"id": 2, "body": "医師 *──1 診療科 1──* 診察 *──1 患者"}, {"id": 3, "body": "医師 1──* 診療科 *──1 診察 1──* 患者"}, {"id": 4, "body": "医師 1──* 診療科 1──* 診察 *──1 患者"}]'::jsonb, 'ipa-original/DMQ-0071.png'),
  ('DMQ-0058', '社員と年との対応関係をUMLのクラス図で記述する。二つのクラス間の関連が次の条件を満たす場合、a、bに入れる多重度の適切な組合せはどれか。ここで、“年”クラスのインスタンスは毎年存在する。

〔条件〕
(1) 全ての社員は入社年を特定できる。
(2) 年によっては社員が入社しないこともある。', '出典：令和4年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問2（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "0..*　0..1"}, {"id": 2, "body": "0..*　1"}, {"id": 3, "body": "1..*　0..1"}, {"id": 4, "body": "1..*　1"}]'::jsonb, 'ipa-original/DMQ-0058.png'),
  ('DMQ-0040', 'JSON形式で表現される図1、図2のような商品データを複数のWebサービスから取得し、商品データベースとして蓄積する際のデータの格納方法に関する記述のうち、適切なものはどれか。ここで、商品データの取得元となるWebサービスは随時変更され、項目数や内容は予測できない。したがって、商品データベースの検索時に使用するキーにはあらかじめ制限を設けない。', '出典：令和5年度 春期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "階層型データベースを使用し、項目名を上位階層とし、値を下位階層とした2階層でデータを格納する。"}, {"id": 2, "body": "グラフデータベースを使用し、商品データの項目名の集合から成るノードと値の集合から成るノードを作り、二つのノードを関係付けたグラフとしてデータを格納する。"}, {"id": 3, "body": "ドキュメントデータベースを使用し、項目構成の違いを区別せず、商品データ単位にデータを格納する。"}, {"id": 4, "body": "関係データベースを使用し、商品データの各項目名を個別の列名とした表を定義してデータを格納する。"}]'::jsonb, 'ipa-original/DMQ-0040.png'),
  ('DMQ-0041', 'UMLを用いて表した図のデータモデルのa、bに入れる多重度はどれか。

〔条件〕
(1) 部門には1人以上の社員が所属する。
(2) 社員はいずれか一つの部門に所属する。
(3) 社員が部門に所属した履歴を所属履歴として記録する。', '出典：令和5年度 春期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "0..*　0..*"}, {"id": 2, "body": "0..*　1..*"}, {"id": 3, "body": "1..*　0..*"}, {"id": 4, "body": "1..*　1..*"}]'::jsonb, 'ipa-original/DMQ-0041.png'),
  ('DMQ-0043', 'ビッグデータ分析の手法の一つであるデシジョンツリーを活用してマーケティング施策の判断に必要な事象を整理し、発生確率の精度を向上させた上で二つのマーケティング施策a、bの選択を行う。マーケティング施策を実行した場合の利益増加額（売上増加額－費用）の期待値が最大となる施策と、そのときの利益増加額の期待値の組合せはどれか。', '出典：令和5年度 春期 応用情報技術者試験 午前 問75（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "a　70"}, {"id": 2, "body": "a　160"}, {"id": 3, "body": "b　82"}, {"id": 4, "body": "b　162"}]'::jsonb, 'ipa-original/DMQ-0043.png')
)
update study.questions as q
set body = o.body,
    source = o.source,
    asset_key = o.asset_key,
    choices = (
      select jsonb_agg(old.choice || jsonb_build_object('body', exact.choice->>'body') order by old.position)
      from jsonb_array_elements(q.choices) with ordinality as old(choice, position)
      join jsonb_array_elements(o.choices) as exact(choice) on old.choice->>'id' = exact.choice->>'id'
    )
from originals as o
where q.id = o.id and q.origin = 'ipa_past'
returning q.id;
-- 原本の図表と設問表現を復元する。
with originals(id, body, asset_key) as (values
  ('DMQ-0002', 'UMLを用いて表した商品と倉庫のデータモデルに関する記述のうち、適切なものはどれか。ここで、商品の倉庫間の移動はないものとする。', NULL),
  ('DMQ-0003', 'データモデルを解釈してオブジェクト図を作成した。解釈の誤りを適切に指摘した記述はどれか。ここで、モデルの表記にはUMLを用い、オブジェクト図の一部の属性の表示は省略した。', NULL),
  ('DMQ-0008', '表のような製品A、Bを製造、販売する場合、考えられる利益は最大で何円になるか。ここで、機械の年間使用可能時間は延べ15,000時間とし、年間の固定費は製品A、Bに関係なく15,000,000円とする。', 'ipa-original/DMQ-0008.png'),
  ('DMQ-0012', '製品X、Yを1台製造するのに必要な部品数は、表のとおりである。製品1台当たりの利益がX、Yともに1万円のとき、利益は最大何万円になるか。ここで、部品Aは120個、部品Bは60個まで使えるものとする。', 'ipa-original/DMQ-0012.png'),
  ('DMQ-0013', '著作権法において、保護の対象とな̲り̲得̲な̲い̲も̲の̲はどれか。', NULL),
  ('DMQ-0036', '化粧品の製造を行っているA社では、販売代理店を通じて商品販売を行っている。今後の販売戦略に活用するために、次の三つの表を設計した。これらの表を用いるだけでは得̲る̲こ̲と̲の̲で̲き̲な̲い̲情̲報̲はどれか。', 'ipa-original/DMQ-0036.png')
)
update study.questions as q
set body = o.body,
    source = replace(q.source, '。表を項目一覧にテキスト化', ''),
    asset_key = coalesce(o.asset_key, q.asset_key)
from originals as o
where q.id = o.id and q.origin = 'ipa_past'
returning q.id;
-- デプロイ済みの画面でも、原文に戻した選択肢に個別解説を表示する。
with explanations(id, details) as (values
  ('DMQ-0062', '{"1":"文書単位で柔軟な構造を保持するドキュメント型の説明である。","2":"つながりそのものを保存し、ノードだけでなく関係にも属性を持たせられる。","3":"キーから対応する値を取り出すキー・バリュー型の説明である。","4":"キーに複数の列を対応させ、列の型をあらかじめ固定しないワイドカラム型の説明である。"}'::jsonb),
  ('DMQ-0063', '{"1":"顧客から注文、注文から明細が1対多になり、明細から商品が多対1になる。","2":"aを商品にすると各注文に対応する商品が一つに限定され、複数の商品を注文できる条件に反する。","3":"bが明細、cが顧客になると、一つの明細に複数の顧客を対応させる構造になる。","4":"明細が一つの商品を指す関係を、明細から商品への1対多としてしまっている。"}'::jsonb),
  ('DMQ-0064', '{"1":"関連や規則を見つけるデータマイニングの説明であり、保存の仕組みを述べていない。","2":"対象部門や目的に応じてデータを絞るデータマートの説明である。","3":"複数の軸で集計するOLAPなどの分析処理であり、データ基盤の格納方式ではない。","4":"先に用途を一つに固定せず、後で分析などの目的に合わせて加工できる。"}'::jsonb),
  ('DMQ-0065', '{"1":"別の利用者と行動が似ていることを根拠に推薦している。","2":"カテゴリ全体で人気の商品を選ぶ方法であり、対象者と似た行動を取った人は探していない。","3":"年齢などの属性であらかじめ区分しており、行動履歴の類似度を使っていない。","4":"商品の用途上の関係を使う例で、利用者間の行動の類似性を評価していない。"}'::jsonb),
  ('DMQ-0066', '{"1":"要因を矢印で結んで因果関係を調べる連関図法の使い方である。","2":"結果とその原因候補を魚の骨に似た配置で表す特性要因図である。","3":"カードを意味の近さでまとめる親和図法である。","4":"手段を次の段階の目的として掘り下げるので、目的と手段の関係が階層として表れる。"}'::jsonb),
  ('DMQ-0067', '{"1":"IDによる結合は、同じIDを持つ左右の行を横につなげる演算である。","2":"RとSの差集合では、RにありSにない行だけが残る。Sにだけある行は含まれない。","3":"直積はRの各行とSの各行を総当たりで組み合わせるので、3×2＝6行になる。","4":"重複している(0001, a, 100)だけを1行にまとめ、その他は両方の関係から残している。"}'::jsonb),
  ('DMQ-0068', '{"1":"受注ごとに複数行あっても、個々の欄に一つの値しか入らないため第1正規形である。","2":"主キーのうち項番がなくても受注日を決められるため、非キー属性が主キーの一部に従属している。","3":"商品コードから単価が決まることに加え、受注番号への部分従属があるので、第2正規形の段階で条件を満たさない。","4":"第3正規形を検討するには、まず受注と明細を整理して部分従属を取り除く必要がある。"}'::jsonb),
  ('DMQ-0069', '{"1":"複製の有無ではなく、異なる製品や環境の違いを隠すことを説明している。","2":"一つの表を部分に分ける分割透過性の説明である。","3":"データの場所を隠す位置透過性の説明である。","4":"同じ表を複数箇所に保存しているという実装上の事情が、利用側から見えない。"}'::jsonb),
  ('DMQ-0070', '{"1":"最も不利なケースでも10円上がり、四つの候補で最小値が最も高い。","2":"最も不利なケースは5円であり、Aの10円より小さい。","3":"好条件の30円ではなく、最も不利な5円を比較する。Aより小さい。","4":"最大40円の上昇があり得る一方、最も不利な場合は10円下がるので、この原理では選ばれない。"}'::jsonb),
  ('DMQ-0071', '{"1":"医師と診療科は合うが、診療科から診察と診察から患者の両方が逆である。","2":"診療科は複数の医師や診察に対応し、患者は複数の診察に対応できる。","3":"医師・診療科・診察・患者のいずれの関連も、外部キーが指す方向から読み取れる多重度と逆になっている。","4":"診療科と診察、診察と患者は合うが、医師から診療科を参照する関連は多対1である。"}'::jsonb),
  ('DMQ-0050', '{"1":"インデックスはデータへの物理的なアクセスを助ける構造に当たる。","2":"E-Rモデルは業務で扱う実体や関連を表し、物理格納を定めない。","3":"整合性制約はデータが満たすべき論理的な規則を記述する。","4":"正規化は属性の従属関係から表の論理構造を整理する作業である。"}'::jsonb),
  ('DMQ-0051', '{"1":"繰返しの解消は第1の特徴であり、第3に対応させると順序が合わない。","2":"第1の特徴である繰返しの解消を第2に、部分従属の解消を第1に割り当てている。","3":"繰返し、部分従属、推移従属の順になっており、各正規形に対応する。","4":"第1の対応は正しいが、第2と第3で解消する従属関係が逆になっている。"}'::jsonb),
  ('DMQ-0052', '{"1":"既知の条件に合う行を探すだけでなく、データから未知の関係を見つけようとしている。","2":"部門向けデータマートの整備であり、格納先を分ける作業が中心である。","3":"データモデルの設計であり、蓄積済みデータから規則を発見する作業ではない。","4":"レプリケーションによる配置・運用の改善であり、データ分析は行っていない。"}'::jsonb),
  ('DMQ-0053', '{"1":"診療記録の共有を主目的とする形式ではない。","2":"顧客台帳や取引履歴を管理するための形式ではない。","3":"企業が公表する財務諸表などを機械で扱いやすい形で表す用途が代表的である。","4":"住民情報の管理を主目的とする形式ではない。"}'::jsonb),
  ('DMQ-0054', '{"1":"3回の条件付き確率を全て掛け、約分した値と一致する。","2":"約0.751は1回目の良品確率0.9の3乗より大きい。良品を戻さない条件では、2回目以降の条件付き確率は下がる。","3":"約0.809は3回すべて成功する確率として大きすぎる。1回ごとに良品確率は約0.9で、これらを掛ける必要がある。","4":"約0.897は1回試す場合に近い。2回目と3回目にも良品を引く条件が必要である。"}'::jsonb),
  ('DMQ-0055', '{"1":"別領域のモデルを使う転移学習の説明であり、訓練時と利用時の性能差を指さない。","2":"訓練例にはよく当てはまるのに未知の例に対応できず、モデルの汎化性能が低い状態である。","3":"誤差逆伝播などのパラメーター更新手順であり、その結果が過学習するとは限らない。","4":"報酬を使って行動を改善する強化学習の説明である。"}'::jsonb),
  ('DMQ-0056', '{"1":"先行指標を使う方法であり、専門家への反復調査は含まれない。","2":"数理モデルによる予測で、見解を集約して再調査する方式ではない。","3":"観測データを使う統計的な比較であり、専門家の判断を繰り返し集めない。","4":"専門家の意見を集約してフィードバックし、段階的に予測をまとめるという特徴がある。"}'::jsonb),
  ('DMQ-0057', '{"1":"2相コミットは参加ノード全体で処理の確定をそろえる仕組みであり、BASE特性がこれを必須とするわけではない。","2":"一時的な差を許しながら、更新を伝播させて最終的に同じ状態へ収束させる。","3":"直ちに同じ結果が返るという強い保証は、結果整合性では求めない。","4":"分断時には全要求を必ず拒否するという説明は、可用性を重視するBASEの考え方とは異なる。"}'::jsonb),
  ('DMQ-0058', '{"1":"年ごとの社員数は合っているが、bが0を含むため入社年のない社員を許す。","2":"aは0人から複数人まで、bはちょうど1年を表し、両方の条件を満たす。","3":"aは入社者のいない年を許さず、bは入社年のない社員を許してしまう。","4":"bは合っているが、aが1以上なので入社者のいない年を表現できない。"}'::jsonb),
  ('DMQ-0040', '{"1":"単純な2階層では商品ごとのまとまりを捉えにくく、配列を含む値も自然に表せない。","2":"項目名と値を集合に分けるだけでは、どの項目がどの値に対応するかを保持しにくい。","3":"必要なフィールドや配列を商品単位で保持でき、全レコードに共通の項目集合を要求しない。","4":"不明な項目をすべて列として先に定義することはできない。"}'::jsonb),
  ('DMQ-0041', '{"1":"どちらも0件を許すため、社員がいる部門や所属が必須の社員にも履歴がない状態を許してしまう。","2":"社員に履歴を要求する点は合うが、部門にも現在の所属に対応する履歴が必要となる。","3":"部門に履歴を要求する点は合うが、社員にも現在の所属に対応する履歴が必要となる。","4":"現在の所属を1件以上、過去の所属を必要に応じて追加する条件を双方で表せる。"}'::jsonb),
  ('DMQ-0042', '{"1":"計算機の資源を仮想サーバとして提供する方式であり、センサーで実物を継続的に再現する仕組みとは異なる。","2":"電力の需要と供給を計測・制御する電力網の考え方である。","3":"電力使用量などを計測して通信できる計器であり、計測値を反映する仮想モデルの名称ではない。","4":"稼働中のエンジンをセンサー値で仮想モデルに反映し、交換時期を予測する点が該当する。"}'::jsonb),
  ('DMQ-0043', '{"1":"aを選んだ場合の期待利益としては正しいが、bの82億円を下回る。","2":"分岐ごとの確率で重み付けし、初期・追加費用を引くと、aの期待利益は70億円となる。","3":"bの追加施策ありの分岐は売上増加の期待値120から追加費用40を引くと80。これを他方の分岐と合わせ、初期費用を引くと82になる。","4":"bの売上増加はどの分岐でも150億円以下なので、費用を引いた期待利益が162億円になることはない。"}'::jsonb),
  ('DMQ-0044', '{"1":"参照先の行に対応するキーを示す点が外部キーの特徴である。","2":"主キーに選ばれなかった候補キーは代替キーである。外部参照の有無を説明していない。","3":"最小性を備えた一意識別子は候補キーである。","4":"識別に不要な属性まで含められる一意識別子はスーパーキーである。"}'::jsonb),
  ('DMQ-0045', '{"1":"性格は個人の心理特性に基づく分類軸である。","2":"職業は消費者本人の属性であり、この分類では人口統計的変数になる。","3":"人口密度は特定の地域の特徴を示すため、この分類では地理的変数に当たる。","4":"製品をどう使うかという行動に着目するので、行動的変数である。"}'::jsonb),
  ('DMQ-0046', '{"1":"故障につながり得る要因を枝分かれさせる図で、件数による優先順位を表すことが主目的ではない。","2":"原因を件数順に並べ、主要な原因が全体の何割を占めるか読み取れる。","3":"縦と横の項目がどの程度関係するかを交点で表す。原因を件数順に比較する用途とは異なる。","4":"要因間の因果関係を矢印で結ぶ図で、上位の原因の累積割合を見せる図ではない。"}'::jsonb),
  ('DMQ-0047', '{"1":"第三者に渡る情報の項目と渡し方をあらかじめ公表することが求められる。","2":"適正な提供を行うたびに、提供内容の事後報告を行うという規定ではない。","3":"提供方法の公表は必要だが、紙などの物理媒体に限定する義務はない。","4":"適正な匿名加工情報について、第三者提供のたびに本人同意を求めるという規定ではない。"}'::jsonb),
  ('DMQ-0048', '{"1":"複数ノードで取引の確定・取消しをそろえる手続であり、データの分割そのものではない。","2":"ハッシュ値で配置先を決め、ノード増減時の再配置を抑える手法である。設問は文字の範囲で割り当てている。","3":"ノードごとに異なる部分集合を持たせるので、データの水平分割に当たる。","4":"同じ内容の複製を別ノードに置く方式であり、部分集合を分けて置く方式とは目的が異なる。"}'::jsonb),
  ('DMQ-0049', '{"1":"氏名では同姓同名を区別できず、同じ社員の複数言語も記録できない。","2":"言語を単独のキーにすると、同じ言語を使う別の社員の行が重複とされる。","3":"番号を単独のキーにすると、同じ社員の2言語目の行を追加できない。","4":"二列の組が重複する場合だけを排除するので、社員と言語の多対多に対応できる。"}'::jsonb)
)
update study.questions as q
set choices = (
  select jsonb_agg(
    case when old.choice ? 'explanation' then old.choice
         else old.choice || jsonb_build_object('explanation', e.details->(old.choice->>'id')) end
    order by old.position
  )
  from jsonb_array_elements(q.choices) with ordinality as old(choice, position)
)
from explanations as e
where q.id = e.id and q.origin = 'ipa_past'
returning q.id;
